NEW_FILES = {'tests/test_civic_rooms.py': '"""A chapel, a courtroom, an assembly hall and a gallery are furnished as what they are (0.270.0, the factory\'s\nroadmap 308). These words were one `hall` kind with a dining hall\'s recipe, and a chapel stood a service counter,\nvending and dining tables. FAILS ON 0.269.0: no such kinds, no front, no facing rows, no pew."""\nimport os\nimport sys\n\nsys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\nimport level_design   # noqa: E402\nimport prop_species   # noqa: E402\n\n\ndef _spec(rid, w=24.0, d=12.0, door_x=None, volumes=()):\n    """One room the shell, a door in its west (low-x) wall unless `door_x` says where in the south one."""\n    s = {"name": "civic_probe", "seed": 1997, "story_height": 4.0,\n         "footprint_x": w, "footprint_y": d, "n_stories": 1,\n         "rooms": [{"id": rid, "story": 0, "role": "public_entry",\n                    "bounds": [-w / 2, -d / 2, w / 2, d / 2], "combat_range": "medium"}],\n         "ext_walls": [{"wall": "W", "story": 0, "openings": [{"kind": "door", "pos": 0.0, "width": 1.8}]}]\n         if door_x is None else\n         [{"wall": "S", "story": 0, "openings": [{"kind": "door", "pos": door_x / w, "width": 1.8}]}],\n         "volumes": list(volumes), "partitions": [], "stairs": []}\n    return s\n\n\ndef test_the_civic_words_have_their_own_kinds():\n    k = level_design._room_kind\n    assert k({"id": "chapel"}) == "chapel"\n    assert k({"id": "viewing_wing"}) == "chapel"\n    assert k({"id": "main_courtroom"}) == "courtroom"\n    assert k({"id": "courtrooms"}) == "courtroom"\n    assert k({"id": "assembly_hall"}) == "assembly"\n    assert k({"id": "north_galleries"}) == "gallery"\n    assert k({"id": "artifact_wing"}) == "gallery"\n    assert "hall" not in level_design._RECIPES\n    assert prop_species.species_for_name("pew_row_a") == "pew"\n\n\ndef test_the_front_is_the_end_away_from_the_door():\n    s = _spec("chapel")\n    assert level_design.room_front(s, s["rooms"][0]) == (True, 1)\n\n\ndef test_an_authored_row_turns_the_axis():\n    row = {"name": "pew_row_a", "x": 0.0, "y": 0.0, "z": 0.45, "size_x": 8.0, "size_y": 0.9, "size_z": 0.9,\n           "collision": "convex", "material": "wood"}\n    s = _spec("chapel", door_x=0.0, volumes=[row])\n    along_x, _sign = level_design.room_front(s, s["rooms"][0])\n    assert along_x is False\n\n\ndef test_a_chapel_is_an_altar_and_pews_all_facing_it():\n    s = _spec("chapel")\n    level_design.furnish(s)\n    names = [v["name"] for v in s["volumes"]]\n    pews = [v for v in s["volumes"] if v["name"].startswith("pew_")]\n    assert len(pews) >= 4, names\n    assert sum(n.startswith("table_work_") for n in names) == 1\n    assert not any(n.startswith(("counter_service_", "vending_", "table_dining_", "chair_waiting_")) for n in names)\n    assert len({v.get("rot_z") for v in pews}) == 1, "every pew faces one way"\n    altar = next(v for v in s["volumes"] if v["name"].startswith("table_work_"))\n    assert altar["x"] > max(v["x"] for v in pews), "the altar stands at the front, beyond the rows"\n    # a centre aisle: no pew crosses the room\'s middle line across the rows\n    assert not any(abs(v["y"]) < v["size_y"] / 2.0 for v in pews)\n\n\ndef test_a_courtroom_has_its_bench_and_a_well_before_the_public():\n    s = _spec("courtroom", w=30.0, d=14.0)\n    level_design.furnish(s)\n    by = lambda stem: [v for v in s["volumes"] if v["name"].startswith(stem + "_")]\n    bench, tables, pews = by("counter_service"), by("table_work"), by("pew")\n    assert len(bench) == 1 and len(tables) == 2 and pews\n    assert bench[0]["x"] > max(t["x"] for t in tables) > max(p["x"] for p in pews)\n\n\ndef test_a_gallery_keeps_its_floor_open():\n    s = _spec("galleries", w=30.0, d=14.0)\n    level_design.furnish(s)\n    r = s["rooms"][0]\n    assert level_design.room_floor_share(s, r) < 0.12\n    assert not any(v["name"].startswith(("counter_service_", "vending_", "table_dining_")) for v in s["volumes"])\n', 'migrations/migrate_civic_rooms.py': '#!/usr/bin/env python3\n"""\nmigrate_civic_rooms.py  --  the civic rooms refurnished as what they are (0.270.0)\n=================================================================================\nOne-shot, idempotent migration over specs/*.json, lf_ specs excepted. Every spec holding a room of the four kinds\n0.270.0 split out of `hall` -- chapel, courtroom, assembly, gallery (`level_design._ROOM_KINDS`) -- is refurnished\n(`migrate_furnish_recipes.migrate`), then given, in the order they shipped, the passes the library is a fixed point of: the shelter pass\n(`migrate_shelter`), the seeded pieces\' corridor and their line (`migrate_seed_corridor`, `migrate_seed_lines`) and the\nwall trim (`migrate_wall_crossing`). Those rooms\' furniture was a dining hall\'s, and a chapel of pews is new input to\neach: the first trial left three chapels short of shelter, the second a viewing wing\'s new shelter out of line. Measured on the twelve such specs before this was written: every volume outside those rooms is the\nsame after as before. A spec none of whose civic rooms still holds a piece only the old recipe stood (`OLD_STEMS`) is\nalready migrated and is not touched.\n\n    python migrations/migrate_civic_rooms.py            # write specs/\n    python migrations/migrate_civic_rooms.py --check    # report only\n"""\nimport glob\nimport io\nimport json\nimport os\nimport sys\n\nROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))\nsys.path.insert(0, ROOT)\nsys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))\n\nimport level_design  # noqa: E402\nimport migrate_furnish_recipes  # noqa: E402\nimport migrate_seed_corridor  # noqa: E402\nimport migrate_seed_lines  # noqa: E402\nimport migrate_shelter  # noqa: E402\nimport migrate_wall_crossing  # noqa: E402\n\nCIVIC = ("chapel", "courtroom", "assembly", "gallery")\n\n\ndef civic_rooms(d):\n    return [r for r in d.get("rooms") or [] if level_design._room_kind(r, d.get("name")) in CIVIC]\n\n\n#: What only the old `hall` recipe stood in these rooms: a room still holding one is not yet migrated.\nOLD_STEMS = ("vending_", "table_dining_", "chair_waiting_", "cigarettes_", "litter_bin_")\n\n\ndef migrated(d, rooms):\n    """Is every civic room clear of what the dining hall\'s recipe stood? Asked of the old pieces, not the new: a\n    first version asked whether a room stood a pew or a case, and a gallery too small to hold either\n    (landmark_hall_a01\'s 7.5 x 7.8 m artifact room) was refurnished on every run."""\n    for r in rooms:\n        tag = "_%s_" % level_design._room_tag(r)\n        for v in d.get("volumes") or []:\n            name = str(v.get("name", ""))\n            if tag in name and name.startswith(OLD_STEMS):\n                return False\n    return True\n\n\ndef main():\n    check = "--check" in sys.argv\n    done = 0\n    for p in sorted(glob.glob(os.path.join(ROOT, "specs", "*.json"))):\n        if os.path.basename(p).startswith("lf_"):\n            continue\n        try:\n            d = json.load(open(p, encoding="utf-8"))\n        except ValueError:\n            continue\n        if not isinstance(d, dict):\n            continue\n        rooms = civic_rooms(d)\n        if not rooms or migrated(d, rooms):\n            continue\n        done += 1\n        if not check:\n            migrate_furnish_recipes.migrate(d)\n            migrate_shelter.migrate(d)\n            migrate_seed_corridor.migrate(d)\n            migrate_seed_lines.migrate(d)\n            migrate_wall_crossing.migrate(d)\n            io.open(p, "w", encoding="utf-8", newline="\\n").write(json.dumps(d, indent=1) + "\\n")\n    print("[civic_rooms] %d spec(s) refurnished%s" % (done, " -- check only, nothing written" if check else ""))\n\n\nif __name__ == "__main__":\n    main()\n'}
CHANGELOG = '## [0.270.0] - a chapel, a courtroom, an assembly hall and a gallery furnished as what they are\n\n**The factory\'s roadmap 308.** One `hall` kind covered the words gallery, galleries, exhibit, chapel, assembly,\ncourtroom, courtrooms, viewing and artifact, and its recipe was a dining hall\'s: a service counter, waiting chairs,\na shelf run, a file cabinet, vending, dining tables, a litter bin and a cigarette machine. Fifteen rooms in twelve\nspecs stood a cafeteria: a funeral home\'s chapel and viewing rooms, two courtrooms, two assembly halls, three\nmuseums\' galleries, a mansion\'s gallery and final_stand\'s.\n\n### Changed\n- **Four kinds where there was one** (`_ROOM_KINDS`): `chapel` (chapel, viewing), `courtroom` (courtroom,\n  courtrooms), `assembly` (assembly), `gallery` (gallery, galleries, exhibit, artifact). `hall` is gone.\n- **A room\'s front** (`room_front`, `room_openings`): an end of its long axis. It is the end whose own wall has\n  less doorway, and between two walls with as much, the end away from the doors\' mean. An authored seat row\n  (`pew`, `bench` in its name) turns the axis so furnish continues it. Each rule was measured on the library:\n  - landmark_hall_a02 has three doors in each long wall, and the mean alone put the front on a wall of doors;\n  - funeral_home_a01\'s chapel\'s authored 8 m pews run across the long axis.\n- **Facing rows** (`facing_slots`, furnish\'s `_facing`, the recipe\'s `facing`): laid first. In order:\n  - a front piece centred on the front wall, sliding a metre at a time off a door\'s approach, facing back into the\n    room;\n  - any well pieces in a row before it;\n  - rows of `seat` across the room, all facing the front: two blocks either side of a centre aisle, with side\n    aisles. A wide block is several pews with aisles between them. Rows run from `gap` off the front wall to a\n    door\'s clearance off the back wall, until `share` or `rows`.\n\n  Every slot is asked of the room as it stands before any row is written (`_row_clear`), so rows keep their aisles\n  from everything but one another; pews stand `FACING_ROW_GAP` 0.3 m apart.\n- **A room that faces a front reserves its routes** (`reserves_routes` -> `"all"`, as a corner store\'s rows have\n  since 0.250.0). Unreserved, landmark_hall_a01\'s assembly hall stood a block of pews across its door to `entry_e`\n  (16.3 -> 20.8 m in the route census); reserved, its worst detour is 1.068.\n- **The recipes:**\n  - chapel: an altar (`table_work`) and pews, 12 rows;\n  - courtroom: the judge\'s bench (`counter_service`), two counsel tables in the well, the public\'s pews 6 m back,\n    6 rows, clerk\'s cabinets on the walls, 6 pieces at most;\n  - assembly: a lectern (`table_work`) and pews, 12 rows;\n  - gallery: display cases and shelf runs on the walls and a short pew or two to look from (`pew_short`, 2.4 and\n    1.8 m: a floor piece\'s spot stands a metre off the room\'s bounds, and a 4.2 m pew turned 0.45 m through the\n    generated compound\'s south wall), one piece in 40 m2, 10 at most.\n\n  The rows are capped because every pew is its own mesh: courthouse_a02\'s first trial stood 60 where the cafeteria\n  had 21 pieces.\n- **`pew`**, a floor piece (3.6 / 3.0 / 2.4 / 4.2 x 0.62 x 0.95 m, front, 60 at most), built by Zoo\'s `pew`\n  (>= 1.130.0); `prop_species` routes `pew` names there before `chair`. That includes the funeral home\'s authored\n  `pew_row` boxes.\n- **The library refurnished** (`migrations/migrate_civic_rooms.py`): the twelve specs with civic rooms, then, in the\n  order they shipped, the passes the library is a fixed point of -- shelter, the seeded pieces\' corridor and line,\n  the wall trim; every volume outside those rooms unchanged. A spec is migrated when none of its civic rooms holds a\n  piece only the old recipe stood.\n- **Cigarette machines 85 -> 71**: the 14 that stood in these rooms.\n\n### Measured (the factory\'s `patches/dc_civic_rooms/route_summary.out.txt`)\n- The route census on the twelve specs, before and after: no route closed to a body or to the bake. Pairs past the\n  guide\'s 1.10 detour are unchanged in every spec. funeral_home_a01\'s chapel narrows 6 pairs to single file, and\n  courthouse_a02 narrows 2. The worst new detour is 1.073 (funeral_home_a01\'s chapel).\n\n### Noted, not changed\n- A courtroom of 42 m (courthouse_a02) keeps most of its floor open behind six rows. Naming that floor\'s use is the\n  factory\'s roadmap 306.\n- Authored boxes in a room refuse the slots beside them, and two rooms\' blocks come out uneven\n  (landmark_hall_a01: 12 pews and 6).\n- A courtroom\'s rail, a lectern and a plinth are not built: no piece or species makes them yet.\n- **Three rooms gain a seeded shelter piece**: funeral_home_a01\'s chapel (a kiosk) and viewing_wing, and\n  funeral_home_a02\'s viewing_rooms (crate stacks). The cafeteria\'s vending machines and shelves had given them\n  shelter-height cover; pews are 0.95 m. They stand in line (`tests/test_seed_lines.py`, lined rooms 35 -> 38). It\n  keeps the rooms fightable, but a crate stack in a viewing room is an odd sight. A shelter-height piece that belongs\n  in a chapel is open.\n\n### Tests\n- `tests/test_civic_rooms.py`: the kinds; the front away from the door; an authored row turning the axis; a chapel\n  as one altar and pews all facing it across a centre aisle, with no cafeteria piece; a courtroom\'s bench, well and\n  public in that order; a gallery\'s floor kept open. Fails on 0.269.0.\n- `tests/test_furnish.py` (the `pew` range), `tests/test_club_fixtures.py` (an exhibit hall stands no cigarette\n  machine; the library\'s 71), `tests/test_seed_lines.py` (38 lined rooms).\n\n'
OLD_VERSION, NEW_VERSION = 'Deli Counter 0.269.0', 'Deli Counter 0.270.0'


def _sha(b):
    return hashlib.sha256(b).hexdigest()[:16]


def _read(name):
    """The file's LF text and whether it is CRLF on disk; refuses mixed endings and a file that is not the pinned one."""
    raw = (REPO / name).read_bytes()
    crlf, lf = raw.count(b"\r\n"), raw.count(b"\n")
    if crlf not in (0, lf):
        raise SystemExit("REFUSED: deli_counter/%s has mixed line endings (%d CRLF of %d); nothing written"
                         % (name, crlf, lf))
    text = raw.decode("utf-8").replace("\r\n", "\n")
    if _sha(text.encode("utf-8")) != PINS[name]:
        raise SystemExit("REFUSED: deli_counter/%s is %s, not the %s this patch was written against; nothing "
                         "written" % (name, _sha(text.encode("utf-8")), PINS[name]))
    return text, crlf > 0


def main(argv):
    # every file worked out and checked before any is written
    out = {}
    for name, edits in EDITS.items():
        text, crlf = _read(name)
        for what, old, new in edits:
            if text.count(old) != 1:
                raise SystemExit("REFUSED: deli_counter/%s: the anchor at %s is there %d times; nothing written"
                                 % (name, what, text.count(old)))
            text = text.replace(old, new)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    # a refurnished spec is carried whole, the file it replaces pinned like any other
    for name, text in REPLACED.items():
        _old, crlf = _read(name)
        out[name] = text.replace("\n", "\r\n") if crlf else text
    for name in NEW_FILES:
        if (REPO / name).exists():
            raise SystemExit("REFUSED: deli_counter/%s exists already; nothing written" % name)
    v = REPO / "VERSION"
    if v.read_bytes().decode("utf-8") != OLD_VERSION:
        raise SystemExit("REFUSED: VERSION reads %r, not %s; nothing written" % (v.read_text(), OLD_VERSION))
    cl = REPO / "CHANGELOG.md"
    craw = cl.read_bytes()
    if b"\r\n" in craw or not craw.startswith(b"## [" + OLD_VERSION.split()[-1].encode() + b"]"):
        raise SystemExit("REFUSED: CHANGELOG.md is not LF opening on %s; nothing written" % OLD_VERSION)
    for name, text in out.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    for name, text in NEW_FILES.items():
        (REPO / name).write_bytes(text.encode("utf-8"))
    v.write_bytes(NEW_VERSION.encode("utf-8"))
    cl.write_bytes(CHANGELOG.encode("utf-8") + craw)
    print("%s applied: %d files edited, %d written, VERSION, CHANGELOG. Now, in deli_counter/: build.py --all, "
          "suite" % (NEW_VERSION, len(out), len(NEW_FILES)))
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
